    /// <summary>
    /// Starts the web server, configuring ASP.NET Core services, authentication,
    /// static file handling, and request routing.
    /// </summary>
    /// <param name="args">Command‑line arguments passed to the builder.</param>
    public static void Server(string[] args)
    {
        var builder = CreateAndSetupBuilder(args, setupDatabase: true);
        Globals.StartTime = DateTime.Now;

        var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("BC850C86FD8E Connection string 'DefaultConnection' not found.");
        builder.Services.AddDbContext<ApplicationDbContext>(options =>
            options.UseSqlServer(connectionString));

        builder.Services.AddDatabaseDeveloperPageExceptionFilter();
        builder.Services.AddDefaultIdentity<IdentityUser>(options => options.SignIn.RequireConfirmedAccount = true)
            .AddEntityFrameworkStores<ApplicationDbContext>();

        //========== Add Windows Authentication
        if (Globals.EnableAuthNegotiation)
        {
            // Add services to the container.
            builder.Services.AddAuthentication(NegotiateDefaults.AuthenticationScheme)
               .AddNegotiate();

            builder.Services.AddAuthorization(options =>
            {
                // By default, all incoming requests will be authorized according to the default policy.
                options.FallbackPolicy = options.DefaultPolicy;
            });
        }
        //==========
        builder.Services.AddRazorPages();
        builder.Services.AddServerSideBlazor();
        builder.Services.AddScoped<AuthenticationStateProvider, RevalidatingIdentityAuthenticationStateProvider<IdentityUser>>();

        // Add CORS policy for the artifacts produces by the /render endpoint.
        // These may be consumed by external applications, so we allow cross-origin requests to them.
        // TODO: An alternative would be to set the CORS headers in RenderController.cs 
        // which would mean a more fine-grained control over CORS on a per-endpoint basis.
        builder.Services.AddCors(options =>
        {
            options.AddPolicy("Bovis.Render.CorsPolicy", policy =>
            {
                policy.AllowAnyOrigin()
                      .AllowAnyMethod()
                      .AllowAnyHeader();
            });
        });

        // Add swagger
        builder.Services.AddControllers();
        builder.Services.AddEndpointsApiExplorer();
        builder.Services.AddSwaggerGen();
